//! A `CoreMessagingXP.dll` that loads.
//!
//! `Microsoft.UI.Windowing.Core.dll` imports the 28 C exports of the SDK's
//! `CoreMessagingXP.dll`, and that DLL aborts on load under Wine because it calls
//! `ntdll.NtCreateWaitCompletionPacket`, which no Wine implements. The classes the DLL
//! serves are already answered by `opendispatch`, so what is left is a loadable file with
//! the same export names.

//! Stubs for the exports of `CoreMessagingXP.dll`.
//!
//! Generated by `comptrace stubs` from the PE export table: 28 exports, 28 kept.
//! A stub takes no parameters on purpose; on x86-64 the caller's arguments stay in
//! registers and are ignored, and the HRESULT is what a caller checks.

mod coreui;

/// `E_NOTIMPL`: the name exists so a caller can load and fail honestly.
const E_NOTIMPL: i32 = 0x8000_4001u32 as i32;

#[unsafe(no_mangle)]
pub extern "system" fn CoreMsgCreateSession() -> i32 {
    E_NOTIMPL
}

